package io.elasticore.sample.petstore.domain.model;

import io.elasticore.springboot3.domain.Money;
import io.elasticore.springboot3.validation.InvariantViolationException;
import jakarta.persistence.Entity;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.function.Function;
import org.hibernate.annotations.DynamicUpdate;

/**
 * PurchaseOrder - what is left to write by hand once the DSL has said the
 * rest. Ship and cancel are the DSL's states; each line's price and the sum
 * of the lines are its @snapshot and @compute. What remains is the shop's
 * own pricing policy.
 *
 * The state lives in PurchaseOrderBase, which is regenerated from the DSL.
 */
@Entity
@Table(name = "ps_purchase_order")
@DynamicUpdate
public class PurchaseOrder extends PurchaseOrderBase {

    private static final BigDecimal HUNDRED = BigDecimal.valueOf(100);

    /**
     * Places the order. The lines are already priced and added up
     * (totalWithoutVat); VAT is added and the discount taken off the
     * VAT-inclusive amount, as the Java EE 7 pet store did. Without a
     * delivery address it goes to the customer's home.
     */
    public void place(LocalDate today, Function<Long, Address> homeOf, BigDecimal vatRate, BigDecimal discountRate) {
        if (getOrderDate() != null) throw new InvariantViolationException("order " + getOrderId() + " is already placed");
        if (getDeliveryAddress() == null) setDeliveryAddress(homeOf.apply(getCustomerId()));
        if (getDeliveryAddress() == null) throw new InvariantViolationException("where should the order go? no delivery address");

        Money withoutVat = getTotalWithoutVat();
        Money vat = percent(withoutVat, vatRate);
        Money discount = percent(withoutVat.plus(vat), discountRate);

        setOrderDate(today);
        setVatRate(vatRate);
        setVat(vat);
        setDiscountRate(discountRate);
        setDiscount(discount);
        setTotal(withoutVat.plus(vat).minus(discount).rounded(2));
        raisePlaced();
    }

    private static Money percent(Money amount, BigDecimal rate) {
        return amount.times(rate.divide(HUNDRED, 6, RoundingMode.HALF_UP)).rounded(2);
    }
}
